mapper.update:
UPDATE wall_comment
SET is_deleted = 1
WHERE id = #{commentId}

mapper.select:
SELECT c.id, c.post_id, c.user_uid, c.is_anonymous, c.content, c.media_urls, c.like_count, c.parent_id, c.reply_comment_id, c.reply_user_uid, c.create_time, u.username as nickname, u.avatar, ru.username AS replyNickname FROM wall_comment c LEFT JOIN user u ON c.user_id = u.id LEFT JOIN user ru ON c.reply_user_id = ru.id WHERE c.is_deleted = 0 AND c.parent_id = 0 AND c.post_id IN
#{pid}
ORDER BY c.post_id, c.like_count DESC, c.create_time DESC

mapper.delete:
DELETE FROM wall_post_action
WHERE post_no = #{commentId}
  AND user_uid = #{userUid}
  AND action_type = 'COMMENT_LIKE'

mapper.update:
UPDATE wall_comment
SET like_count = GREATEST(like_count + #{delta}, 0)
WHERE id = #{commentId}
